CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, course_id TEXT NOT NULL, type TEXT NOT NULL, schema INTEGER NOT NULL, recorded_at INTEGER NOT NULL, occurred_at INTEGER NOT NULL, device_id TEXT NOT NULL, actor TEXT NOT NULL, command_id TEXT, effect_index INTEGER NOT NULL, idem_key TEXT NOT NULL, payload_sha256 TEXT, causation_id TEXT, thread_id TEXT, payload TEXT NOT NULL, event_json TEXT NOT NULL, UNIQUE(device_id,command_id,effect_index), UNIQUE(course_id,idem_key));
CREATE INDEX course_events ON events(course_id,seq);
CREATE TABLE command_log(device_id TEXT NOT NULL,command_id TEXT NOT NULL,payload_sha256 TEXT NOT NULL,payload_bytes TEXT NOT NULL,result TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(device_id,command_id));
CREATE TABLE ledger_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),epoch TEXT NOT NULL,backed_up_through_seq INTEGER NOT NULL DEFAULT 0,last_seq_before INTEGER NOT NULL DEFAULT 0,last_backup_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE jobs(job_id TEXT PRIMARY KEY,kind TEXT NOT NULL,subject TEXT NOT NULL,fence INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL CHECK(state IN ('queued','running','completed','failed','cancelled')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,question_version TEXT,answer_hash TEXT);
CREATE TABLE turn_leases(thread_id TEXT PRIMARY KEY,turn_id TEXT NOT NULL UNIQUE,device_id TEXT NOT NULL,fence INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE lease_fences(thread_id TEXT PRIMARY KEY,fence INTEGER NOT NULL);
CREATE TABLE messages(thread_id TEXT NOT NULL,mseq INTEGER NOT NULL,message_id TEXT NOT NULL UNIQUE,role TEXT,model TEXT,mode TEXT,status TEXT NOT NULL CHECK(status IN ('streaming','complete','truncated','cancelled','failed')),reason TEXT,content_md TEXT,citations TEXT,created_at INTEGER,PRIMARY KEY(thread_id,mseq));
CREATE TABLE projection_cache(name TEXT,course_id TEXT,version INTEGER,last_seq INTEGER,blob BLOB,PRIMARY KEY(name,course_id));
CREATE TABLE questions(question_id TEXT PRIMARY KEY,course_id TEXT NOT NULL,format TEXT NOT NULL,stem_md TEXT NOT NULL,options TEXT,origin TEXT NOT NULL,fingerprint TEXT NOT NULL,key_state TEXT NOT NULL,created_seq INTEGER);
CREATE TABLE question_kp(question_id TEXT,kp_id TEXT,is_primary INTEGER,PRIMARY KEY(question_id,kp_id));
CREATE TABLE answer_keys(question_id TEXT PRIMARY KEY,key_json TEXT NOT NULL,reviewed_by TEXT,reviewed_at INTEGER);
CREATE TABLE blobs(sha256 TEXT PRIMARY KEY,size INTEGER NOT NULL,mime TEXT,path TEXT NOT NULL);
CREATE TABLE source_docs(doc_id TEXT PRIMARY KEY,course_id TEXT,kind TEXT,title TEXT,blob_sha256 TEXT,book_page_offset INTEGER,tutor_visible INTEGER);
CREATE TABLE source_pages(doc_id TEXT,pdf_page INTEGER,book_page INTEGER,text TEXT,text_sha256 TEXT,PRIMARY KEY(doc_id,pdf_page));
CREATE TABLE outline_kp(kp_id TEXT PRIMARY KEY,course_id TEXT,module_id TEXT,ord INTEGER,title TEXT,kind TEXT,exam_formats TEXT,prereqs TEXT,anchors TEXT,retired INTEGER,legacy_id TEXT);
CREATE TABLE threads(thread_id TEXT PRIMARY KEY,course_id TEXT,kind TEXT,anchor_type TEXT,anchor_id TEXT,UNIQUE(kind,anchor_type,anchor_id));
CREATE TABLE math_svg(sha256 TEXT PRIMARY KEY,tex TEXT,display INTEGER,svg TEXT,w_em REAL,h_em REAL,d_em REAL);
CREATE TABLE ai_calls(call_id TEXT PRIMARY KEY,task TEXT,requested_model TEXT,served_by TEXT,ttft_ms INTEGER,dur_ms INTEGER,in_chars INTEGER,out_chars INTEGER,status TEXT,request_type TEXT,effort TEXT,pack_chars INTEGER,queue_ms INTEGER,physical_calls INTEGER,cache_read INTEGER,cache_create INTEGER);
CREATE TABLE devices(device_id TEXT PRIMARY KEY,name TEXT,token_sha256 TEXT NOT NULL,created_at INTEGER,revoked_at INTEGER);
CREATE TABLE journal_revisions(course_id TEXT,day INTEGER,rev INTEGER,content_sha TEXT,PRIMARY KEY(course_id,day));
CREATE VIRTUAL TABLE fts_en USING fts5(text,doc_id UNINDEXED,pdf_page UNINDEXED,tokenize='porter unicode61');
CREATE VIRTUAL TABLE fts_zh USING fts5(text,doc_id UNINDEXED,pdf_page UNINDEXED,tokenize='trigram');
